function EdgeCountProfile(points P, scales S):
    D <- empty list
    for i in 0..|P|-1:
        for j in i+1..|P|-1:
            D.append( dist(P[i], P[j]) )      # C(n,2) pairwise distances
    sort(D) ascending
    result <- empty list
    for r in S:
        result.append( count of elements of D that are <= r )  # binary search
    return result                              # nondecreasing by construction

function VerifyDomination(alpha, beta, f_index, scales):
    if f_index has duplicates: return False        # f must be injective
    for each pair (i, j) in alpha:
        if dist(beta[f_index[i]], beta[f_index[j]]) > dist(alpha[i], alpha[j]):
            return False                            # f must be nonexpanding
    for r in scales:
        if EdgeCount(alpha, r) > EdgeCount(beta, r):
            return False                            # conclusion must hold
    return True

